'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var hasIteratorSymbolSupport = require( '@stdlib/assert/has-iterator-symbol-support' );
var ITERATOR_SYMBOL = require( '@stdlib/symbol/iterator' );
var namedtypedtuple = require( './../lib' );


// VARIABLES //

var HAS_ITERATOR_SYMBOL = hasIteratorSymbolSupport();


// FUNCTIONS //

/**
* Returns an iterable object.
*
* @private
* @param {Array} arr - source array
* @returns {Object} iterable object
*/
function createIterable( arr ) {
	var obj = {};
	var i = -1;
	if ( HAS_ITERATOR_SYMBOL ) {
		obj[ ITERATOR_SYMBOL ] = iterator;
	}
	return obj;

	function iterator() {
		return {
			'next': next
		};
	}

	function next() {
		i += 1;
		if ( i < arr.length ) {
			return {
				'value': arr[ i ],
				'done': false
			};
		}
		return {
			'done': true
		};
	}
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof namedtypedtuple, 'function', 'main export is a function' );
	t.end();
});

tape( 'a tuple factory has a `from` method', function test( t ) {
	var Point;

	Point = namedtypedtuple( [ 'x', 'y' ] );

	t.strictEqual( hasOwnProp( Point, 'from' ), true, 'returns expected value' );
	t.strictEqual( isFunction( Point.from ), true, 'returns expected value' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not the host tuple factory', function test( t ) {
	var values;
	var Point;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return Point.from.call( value, [ 1, 2 ] );
		};
	}
});

tape( 'the method throws an error if provided a second argument which is not a function', function test( t ) {
	var values;
	var Point;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );

	values = [
		'5',
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return Point.from( [ 1, 2 ], value );
		};
	}
});

tape( 'the method throws an error if provided a first argument which is not an array-like object or an iterable', function test( t ) {
	var values;
	var Point;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );

	values = [
		5,
		3.14,
		NaN,
		true,
		false,
		null,
		void 0
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return Point.from( value );
		};
	}
});

tape( 'the method throws a range error if provided an array-like object whose length is incompatible with the number of tuple fields', function test( t ) {
	var Point;

	Point = namedtypedtuple( [ 'x', 'y' ] );

	t.throws( badValue, RangeError, 'throws an error' );
	t.end();

	function badValue() {
		return Point.from( [ 1, 2, 3 ] );
	}
});

tape( 'the method creates a new tuple from an array-like object', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = Point.from( [ 10, 20, 30 ] );

	t.strictEqual( p[ 0 ], 10, 'returns expected value' );
	t.strictEqual( p[ 1 ], 20, 'returns expected value' );
	t.strictEqual( p[ 2 ], 30, 'returns expected value' );
	t.deepEqual( p.fields, [ 'x', 'y', 'z' ], 'returns expected value' );
	t.end();
});

tape( 'the method creates a new tuple from an iterable', function test( t ) {
	var Point;
	var p;

	if ( !HAS_ITERATOR_SYMBOL ) {
		t.pass( 'environment does not support Symbol.iterator' );
		return t.end();
	}
	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = Point.from( createIterable( [ 10, 20, 30 ] ) );

	t.strictEqual( p[ 0 ], 10, 'returns expected value' );
	t.strictEqual( p[ 1 ], 20, 'returns expected value' );
	t.strictEqual( p[ 2 ], 30, 'returns expected value' );
	t.deepEqual( p.fields, [ 'x', 'y', 'z' ], 'returns expected value' );
	t.end();
});

tape( 'the method creates a new tuple from an iterable using a callback', function test( t ) {
	var Point;
	var p;

	if ( !HAS_ITERATOR_SYMBOL ) {
		t.pass( 'environment does not support Symbol.iterator' );
		return t.end();
	}
	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = Point.from( createIterable( [ 10, 20, 30 ] ), fcn );

	t.strictEqual( p[ 0 ], 20, 'returns expected value' );
	t.strictEqual( p[ 1 ], 40, 'returns expected value' );
	t.strictEqual( p[ 2 ], 60, 'returns expected value' );
	t.end();

	function fcn( v ) {
		return v * 2;
	}
});

tape( 'the method creates a new tuple from an array-like object using a callback', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = Point.from( [ 10, 20, 30 ], fcn );

	t.strictEqual( p[ 0 ], 20, 'returns expected value' );
	t.strictEqual( p[ 1 ], 40, 'returns expected value' );
	t.strictEqual( p[ 2 ], 60, 'returns expected value' );
	t.end();

	function fcn( v ) {
		return v * 2;
	}
});

tape( 'the callback is invoked with three arguments', function test( t ) {
	var fieldNames;
	var indices;
	var values;
	var Point;

	if ( !HAS_ITERATOR_SYMBOL ) {
		t.pass( 'environment does not support Symbol.iterator' );
		return t.end();
	}
	values = [];
	indices = [];
	fieldNames = [];

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	Point.from( createIterable( [ 10, 20, 30 ] ), fcn );

	t.deepEqual( values, [ 10, 20, 30 ], 'returns expected value' );
	t.deepEqual( indices, [ 0, 1, 2 ], 'returns expected value' );
	t.deepEqual( fieldNames, [ 'x', 'y', 'z' ], 'returns expected value' );
	t.end();

	function fcn( v, i, f ) {
		values.push( v );
		indices.push( i );
		fieldNames.push( f );
		return v;
	}
});

tape( 'the method supports providing a callback execution context', function test( t ) {
	var Point;
	var ctx;

	ctx = {
		'count': 0
	};
	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	Point.from( [ 10, 20, 30 ], fcn, ctx );

	t.strictEqual( ctx.count, 3, 'returns expected value' );
	t.end();

	function fcn( v ) {
		this.count += 1; // eslint-disable-line no-invalid-this
		return v;
	}
});
